after.content:
param(
    [Parameter(Position = 0, Mandatory = $true)]
    [ValidateSet("relay")]
    [string]$Product,
    [Parameter(Position = 1, Mandatory = $true)]
    [ValidateSet("up", "status", "down")]
    [string]$Action
)

$compose = Join-Path $PSScriptRoot "deploy/relay/compose.yaml"
switch ($Action) {
    "up" { docker compose -p ji-relay -f $compose up -d --build --wait }
    "status" {
        docker compose -p ji-relay -f $compose ps
        Invoke-RestMethod -Uri "http://127.0.0.1:18090/api/v1/health/ready" | ConvertTo-Json -Compress
    }
    "down" { docker compose -p ji-relay -f $compose down }
}
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
